// Filtra quem não interage (nao responde no whatsapp) ha 2+ dias
// Pressupoe uma coluna 'ultima_interacao' atualizada pelo Workflow A
// toda vez que a noiva manda mensagem pra Rosa.
const items = $input.all();
const hoje = new Date();
const resultado = [];

for (const item of items) {
  const lead = item.json;
  if (!lead.ultima_interacao) continue;
  const ultima = new Date(lead.ultima_interacao);
  const diasSemInteragir = Math.floor((hoje - ultima) / 86400000);
  if (diasSemInteragir >= 2) {
    resultado.push({ json: { nome: lead.nome, telefone: lead.telefone } });
  }
}
return resultado;
